# Manual evidence-based topic mapping maintained separately from source extraction.
manual = json.loads((p/'vn_research_topic_codes.json').read_text())
by_title = {i['title']: i for school_codes in manual for i in school_codes['items']}
for school_record in schools:
    for research_item in school_record['items']:
        codes = by_title[research_item['title']]
        research_item['topic_codes'] = codes['topic_codes']
        research_item['primary_topic_code'] = codes['primary_topic_code']
        research_item['classification_method'] = 'Manually assigned from research aim, method and application described in source; labels are analyst interpretation.'
        if school_record['domain'] == 'vlute.edu.vn':
            research_item['affiliation_evidence_level'] = 'institutional_author_email_on_publisher_page'
            research_item['verification_note'] += ' Quan hệ với VLUTE được hỗ trợ bởi email tác giả trên trang tạp chí; chưa đối chiếu trang nhân sự hoặc dòng affiliation trong PDF.'
(p/'vn_research.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
print({'schools':len(schools),'items':sum(len(s['items']) for s in schools),'types':dict(collections.Counter(i['type'] for s in schools for i in s['items']))})
